<?php
require __DIR__.'/includes/bootstrap.php';$user=require_user();require __DIR__.'/includes/modules.php';require __DIR__.'/includes/layout.php';page_header('Placement desk',$user);
$metrics=[['requests','New','New client requests'],['applications','New','New candidate applications'],['candidates','Available','Available candidates'],['placements','Agreement Pending','Agreements pending'],['placements','Completed','Completed placements'],['enquiries','New','Unread enquiries'],['applications','Verification Required','Awaiting verification']];
echo '<div class="metrics">';foreach($metrics as [$name,$status,$label]){$m=module($name);$count=query('SELECT COUNT(*) FROM '.$m['table'].' WHERE status=?',[$status])->fetchColumn();echo '<a class="metric" href="'.e(url('admin/list.php?module='.$name.'&status='.rawurlencode($status))).'"><strong>'.(int)$count.'</strong>'.e($label).'</a>';}
$progress=query("SELECT COUNT(*) FROM placements WHERE status IN ('New','Candidate Selected','Agreement Pending','Confirmed','Active')")->fetchColumn();echo '<a class="metric" href="'.e(url('admin/list.php?module=placements')).'"><strong>'.(int)$progress.'</strong>Placements in progress</a></div><section class="panel"><h2>Recent activity</h2><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>When (UTC)</th><th>Action</th><th>Record</th><th>Staff</th></tr></thead><tbody>';
foreach(query('SELECT a.*,u.full_name FROM audit_logs a LEFT JOIN admin_users u ON u.id=a.admin_user_id ORDER BY a.id DESC LIMIT 20')->fetchAll() as $row){echo '<tr><td>'.e($row['created_at']).'</td><td>'.e(str_replace('_',' ',$row['action'])).'</td><td>'.(isset(modules()[$row['entity_type']])&&$row['entity_id']?record_link($row['entity_type'],(int)$row['entity_id']):e($row['entity_type'])).'</td><td>'.e($row['full_name']??'Website / system').'</td></tr>';}
echo '</tbody></table></div></section>';page_footer();
